#ifndef WS_BLOCK_DEQUE_H
#define WS_BLOCK_DEQUE_H

#include <deque>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <optional>
#include <chrono>
#include <cassert>

namespace ws {

template <typename T>
class BlockDeque {
public:
    using Clock = std::chrono::steady_clock;

    BlockDeque(std::size_t capacity = 1000) noexcept {
        assert(capacity > 0);
        capacity_ = capacity;
        closed_ = false;
    }

    BlockDeque(const BlockDeque&) = delete;
    BlockDeque(BlockDeque&&) = delete;
    BlockDeque& operator=(const BlockDeque&) = delete;
    BlockDeque& operator=(BlockDeque&&) = delete;

    ~BlockDeque() noexcept {
        Close();
    }

    void Clear() noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        ClearNoLock();
    }

    bool Empty() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.empty();
    }

    bool Full() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        assert(deq_.size() <= capacity_);
        return deq_.size() == capacity_;
    }

    std::size_t Size() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        return deq_.size();
    }

    std::size_t Capacity() const noexcept {
        return capacity_;
    }

    void PushBack(T item) noexcept {
        std::unique_lock<std::mutex> lock(mtx_);
        WaitForSpace(lock);
        deq_.push_back(std::move(item));
        Flush();
    }

    void PushFront(T item) noexcept {
        std::unique_lock<std::mutex> lock(mtx_);
        WaitForSpace(lock);
        deq_.push_front(std::move(item));
        Flush();
    }

    const T& Front() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        assert(!deq_.empty());
        return deq_.front();
    }

    const T& Back() const noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        assert(!deq_.empty());
        return deq_.back();
    }

    T& Front() noexcept {
        return const_cast<T&>(std::as_const(*this).Front());
    }

    T& Back() noexcept {
        return const_cast<T&>(std::as_const(*this).Back());
    }

    std::optional<T> Pop(std::optional<Clock::duration> time_out = std::nullopt) noexcept {
        std::unique_lock<std::mutex> lock(mtx_);
        if (time_out) {
            if (!consumer_cond_.wait_for(lock, *time_out, [this] { return !deq_.empty() || closed_; })) {
                return std::nullopt;
            }
        } else {
            consumer_cond_.wait(lock, [this] { return !deq_.empty() || closed_; });
        }

        if (closed_) {
            return std::nullopt;
        }

        T item = std::move(deq_.front());
        deq_.pop_front();
        producer_cond_.notify_one();
        return item;
    }

    void Flush() noexcept {
        consumer_cond_.notify_one();
    }

    void Close() noexcept {
        std::lock_guard<std::mutex> lock(mtx_);
        ClearNoLock();
        closed_ = true;
        producer_cond_.notify_all();
        consumer_cond_.notify_all();
    }

private:
    void WaitForSpace(std::unique_lock<std::mutex>& locker) noexcept {
        producer_cond_.wait(locker, [this] { return deq_.size() < capacity_ || closed_; });
    }

    void ClearNoLock() noexcept {
        deq_.clear();
    }

    std::mutex mtx_;
    std::atomic_bool closed_;
    std::size_t capacity_;
    std::deque<T> deq_;
    std::condition_variable consumer_cond_;
    std::condition_variable producer_cond_;
};

}

#endif // WS_BLOCK_DEQUE_H
